class Solution {
    public int[] decrypt(int[] code, int k) {
        int n = code.length;
        int[] res = new int[n];
        if (k == 0) return res;
        for (int i = 0; i < n; ++i) {
            if (k > 0) {
                for (int j = i + 1; j <= i + k; ++j) {
                    res[i] += code[j % n];
                }
            } else {
                for (int j = i + k; j <= i - 1; ++j) {
                    res[i] += code[(j + n) % n];
                }
            }
        }
        return res;
    }
}

class Solution(object):
    def decrypt(self, code, k):
        """
        :type code: List[int]
        :type k: int
        :rtype: List[int]
        """
        n = len(code)
        ans = [0 for _ in range(n)]
        if k == 0:
            return ans
        if k > 0:
            t = 1
        else:
            t = -1
            k = -k
        for i in range(n):
            p = (i + t) % n
            for _ in range(k):
                ans[i] += code[p]
                p = (p + t) % n
        return ans
